<?php use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Stan treści';?>
<div class="page-head"><div><p class="eyebrow">Administracja · Content</p><h1>Stan treści</h1></div><a class="button secondary" href="<?=Html::e(Url::to('/admin/trash'))?>">Kosz</a></div>
<section class="card section-card"><h2>Uszkodzone linki wewnętrzne</h2><?php if(!$broken):?><div class="empty-state"><p>Nie wykryto błędnych linków do stron ani załączników.</p></div><?php endif;?><?php foreach($broken as $b):?><a class="list-row" href="<?=Html::e(Url::to('/pages/'.$b['page_id']))?>"><span><strong><?=Html::e($b['title'])?></strong><small><?=Html::e($b['kind'])?> #<?=Html::e($b['target'])?></small></span></a><?php endforeach;?></section>
<section class="card section-card"><h2>Orphan pages</h2><?php if(!$orphans):?><div class="empty-state"><p>Brak osieroconych stron.</p></div><?php endif;?><?php foreach($orphans as $p):?><a class="list-row" href="<?=Html::e(Url::to('/pages/'.$p['id']))?>"><span><strong><?=Html::e($p['title'])?></strong><small><?=Html::e($p['space_name'])?> · <?=Html::e($p['updated_at'])?></small></span></a><?php endforeach;?></section>
<section class="card section-card"><div class="section-heading"><div><h2>Treść wymagająca przeglądu</h2><p class="muted">Stare strony, brak ownera lub przekroczony review date.</p></div><form method="get"><label>Starsze niż <input type="number" min="1" max="3650" name="days" value="<?=Html::e($days)?>" style="width:7rem"> dni</label><button class="button secondary">Przelicz</button></form></div><?php if(!$stale):?><div class="empty-state"><p>Brak problemów w wybranym zakresie.</p></div><?php endif;?><?php foreach($stale as $p):?><a class="list-row" href="<?=Html::e(Url::to('/pages/'.$p['id']))?>"><span><strong><?=Html::e($p['title'])?></strong><small><?=Html::e($p['space_name'])?> · owner <?=Html::e($p['owner_username']??'brak')?> · aktualizacja <?=Html::e($p['updated_at'])?><?=!empty($p['review_date'])?' · review '.$p['review_date']:''?></small></span></a><?php endforeach;?></section>
